def _(Harness, flow, get_code, get_connection, get_outputs, get_progress, improvement_idea, improvement_step, mo, set_outputs, set_progress, support, ui):
    mo.stop(not improvement_step.value)
    try:
        _ctx, _code = get_connection(), get_code()
        _blocked = flow.blocked("improvement_step", get_progress())
        if _blocked: raise ValueError(_blocked["text"])
        _snapshot = _ctx["client"].snapshot()
        _next = flow.improvement_step(_snapshot)
        if _next.get("complete") or _next.get("blocked"): raise ValueError(_next["label"])
        _number, _phase = _next["round"], _next["phase"]
        def _execute(case_id, stage, harness):
            return _code["run"](_ctx["client"], case_id, stage, harness, _code["runtime"], _code["schema"])
        if _phase == "start":
            _decision = _snapshot["decisions"]["r1_composed"]
            _result = _execute("missing-seat", "r2_start", Harness(**_decision["harness"]))
            _ctx["journal"].put("r2_start", _result)
        else:
            _result = _code["improve"](_ctx["client"], _number, _phase, _execute, improvement_idea.value)
        _ctx["journal"].put(["round", _number, _phase], _result)
        _runs = [r for r in _ctx["client"].snapshot()["runs"] if r["stage"].startswith(f"r{_number}_")]
        _traces = support.export_completed_traces(_ctx, _code, _runs)
        _pending = [t for t in _traces if t["status"] == "export_pending"]
        _action_output = (mo.Html(ui.trace_results(_pending)) if _pending else mo.md("**Step saved.** Review the next action in the workbench above."))
    except Exception as _error:
        _action_output = (mo.callout(str(_error), kind="danger"))
    finally:
        set_outputs({**get_outputs(), "improvement_step": _action_output})
        if get_connection(): set_progress(flow.refresh(get_connection()))
    return


