@app.cell(hide_code=True)
def _(EXERCISE_SOURCES, PUBLIC_SOURCES, get_code, mo, source_file):
    _selected = source_file.value
    if _selected in {"current", "manual"}:
        _harness = get_code().get("employee" if _selected == "current" else "manual")
        if _harness:
            mo.output.replace(mo.vstack([mo.md("**Current draft fingerprint:** `" + _harness.fingerprint + "`. An execution's receipt identifies what ran."), mo.accordion({name: mo.md("```text\n" + content + "\n```") for name, content in _harness.files().items()})]))
        else:
            mo.output.replace(mo.md("Run the free exercise cells first to load your current draft."))
    else:
        _text = PUBLIC_SOURCES[_selected] if _selected in PUBLIC_SOURCES else EXERCISE_SOURCES[_selected]
        mo.output.replace(mo.vstack([mo.md("Bundled source for this release. Your edited functions are visible in their exercise cells."), mo.md("```python\n" + _text + "\n```")]))
    return


